// Simple sampling profiler (signal-based)
#include <signal.h>
#include <ucontext.h>

typedef struct Sample {
    void* pc;          // program counter
    void* stack[64];   // call stack
    int depth;         // stack depth
} Sample;

#define MAX_SAMPLES 100000
static Sample samples[MAX_SAMPLES];
static int sample_count = 0;

void profiler_handler(int sig, siginfo_t* info, void* context) {
    if (sample_count >= MAX_SAMPLES) return;

    ucontext_t* uc = (ucontext_t*)context;
    void** bp = (void**)uc->uc_mcontext.gregs[REG_RBP];
    void* pc = (void*)uc->uc_mcontext.gregs[REG_RIP];

    Sample* s = &samples[sample_count++];
    s->pc = pc;
    s->depth = 0;

    // Walk stack frame chain
    while (bp && s->depth < 64) {
        s->stack[s->depth++] = pc;
        pc = bp[1];      // return address
        bp = (void**)bp[0];  // previous frame pointer
    }
}

void start_profiler() {
    struct sigaction sa = {
        .sa_sigaction = profiler_handler,
        .sa_flags = SA_SIGINFO
    };
    sigemptyset(&sa.sa_mask);
    sigaction(SIGPROF, &sa, NULL);

    // Sample every 10ms
    struct itimerval timer = {
        .it_interval = {0, 10000},  // 10ms
        .it_value = {0, 10000}
    };
    setitimer(ITIMER_PROF, &timer, NULL);
}

